const app=document.getElementById('admin-app');
const state={authed:false,needsSetup:false,remoteSetup:false,tab:'places',edit:null,records:{places:[],articles:[],routes:[],submissions:[]},query:'',filter:'all',routeIds:[],saving:false,fromSubmission:null,maptilerKey:''};
let pickerMap,pickerMarker;
const labels={places:'地圖標點',articles:'人物故事／文章',routes:'主題路線',submissions:'投稿審核'};
const esc=(v='')=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,opts={}){const r=await fetch(url,{credentials:'same-origin',...opts});let data;try{data=await r.json()}catch{data={error:'伺服器回應格式不正確'}}if(!r.ok)throw new Error(data.error||'操作失敗，請重試');return data}
function toast(message){let t=document.querySelector('.toast');if(!t)return;t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
async function init(){try{const [me,config]=await Promise.all([api('/api/admin/me'),api('/api/config')]);state.maptilerKey=config.maptilerKey||'';state.authed=me.authenticated;state.needsSetup=me.needsSetup;state.remoteSetup=Boolean(me.remoteSetup);if(state.authed)await refresh();else render()}catch(error){app.innerHTML=`<div class="login-shell"><div class="login-card"><div class="error">無法連接管理服務：${esc(error.message)}</div></div></div>`}}
async function refresh(){const keys=['places','articles','routes','submissions'];const data=await Promise.all(keys.map(k=>api(`/api/admin/${k}`)));keys.forEach((k,i)=>state.records[k]=data[i]);render()}
function login(){return `<div class="login-shell"><div class="login-card"><div class="brand"><span class="brand-mark">✦</span> 綠門 GO</div><h1>${state.needsSetup?'建立管理員密碼':'登入內容管理'}</h1><p>${state.needsSetup?(state.remoteSetup?'這是雲端首次設定。請輸入部署時建立的一次性設定憑證，再建立管理員密碼。':'這是本機首次設定。密碼建立後，只有登入的管理員可以編輯及發布內容。'):'管理文章、地圖標點、路線與投稿。'}</p><form id="auth-form">${state.needsSetup&&state.remoteSetup?'<label class="field">一次性設定憑證<input type="password" name="setupToken" autocomplete="one-time-code" required></label>':''}<label class="field">管理員密碼<input type="password" name="password" minlength="${state.needsSetup?'12':'1'}" autocomplete="${state.needsSetup?'new-password':'current-password'}" required></label>${state.needsSetup?`<label class="field">再次輸入密碼<input type="password" name="confirm" minlength="12" autocomplete="new-password" required></label>`:''}<button class="btn btn-primary" type="submit">${state.needsSetup?'建立密碼並進入後台':'登入後台'}</button><div id="auth-error"></div></form></div></div>`}
function shell(content){return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">✦</span> 綠門 GO</div><nav class="nav">${Object.entries(labels).map(([key,label])=>`<button data-tab="${key}" class="${state.tab===key?'active':''}">${label}</button>`).join('')}</nav><div class="sidebar-bottom"><a href="/" target="_blank">↗ 查看網站前台</a><button class="btn" data-action="logout">登出</button></div></aside><main class="main">${content}</main></div><div class="toast" role="status" aria-live="polite"></div>`}
function head(){return `<div class="main-head"><div><small>綠門 GO / 內容管理</small><h1>${state.edit?`編輯${labels[state.tab]}`:labels[state.tab]}</h1><p>${state.tab==='places'?'在地圖上放置標點，填好資料後可先存草稿，再發布到前台。':state.tab==='articles'?'編輯人物故事與文章；只有已發布內容會顯示在前台。':state.tab==='routes'?'選擇沿途地點，安排主題路線的先後次序。':'檢視訪客推薦，核實後轉成正式地點。'}</p></div>${state.tab!=='submissions'&&!state.edit?`<button class="btn btn-primary" data-action="new">＋ 新增${labels[state.tab]}</button>`:''}</div>`}
function list(){const key=state.tab,all=state.records[key],query=state.query.toLowerCase(),rows=all.filter(x=>(state.filter==='all'||x.status===state.filter)&&(!query||JSON.stringify(x).toLowerCase().includes(query)));return head()+`<div class="toolbar"><input id="admin-search" aria-label="搜尋內容" placeholder="搜尋名稱或內容…" value="${esc(state.query)}"><select id="admin-filter" aria-label="篩選狀態"><option value="all">全部狀態</option><option value="published" ${state.filter==='published'?'selected':''}>已發布</option><option value="draft" ${state.filter==='draft'?'selected':''}>草稿</option></select></div><div class="table-wrap">${rows.length?`<table class="table"><thead><tr><th>名稱</th><th>${key==='places'?'分類 / 地區':key==='routes'?'地點數':'關聯地點'}</th><th>狀態</th><th>更新時間</th><th>操作</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name||x.title||x.n)}</strong><small>${esc(x.address||x.subtitle||x.text||'')}</small></td><td>${esc(key==='places'?`${x.cat} / ${x.area}`:key==='routes'?`${x.ids?.length||0} 個地點`:state.records.places.find(p=>p.id===x.place_id)?.name||'—')}</td><td><span class="badge ${esc(x.status)}">${x.status==='published'?'已發布':'草稿'}</span></td><td>${esc(x.updated_at?.slice(0,16).replace('T',' ')||'')}</td><td><div class="row-actions"><button class="btn btn-outline" data-edit="${esc(x.id)}">編輯</button><button class="btn btn-danger" data-delete="${esc(x.id)}">刪除</button></div></td></tr>`).join('')}</tbody></table>`:`<div class="empty">沒有符合條件的內容。</div>`}</div>`}
const field=(name,label,value='',opts='')=>`<label class="field ${opts.includes('wide')?'wide':''}">${label}<input name="${name}" value="${esc(value)}" ${opts.replace('wide','')}></label>`;
const textarea=(name,label,value='',rows=5)=>`<label class="field wide">${label}<textarea name="${name}" rows="${rows}">${esc(value)}</textarea></label>`;
const select=(name,label,options,value='')=>`<label class="field">${label}<select name="${name}">${options.map(o=>`<option value="${esc(o)}" ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
function imageField(r){return `<div class="panel"><h2>封面圖片</h2><label class="field">上傳圖片<input type="file" id="image-file" accept="image/jpeg,image/png,image/webp"></label><img class="image-preview" id="image-preview" src="${esc(r.img||'')}" alt="圖片預覽" ${r.img?'':'hidden'}><input type="hidden" name="img" value="${esc(r.img||'')}"><span class="helper">接受 JPG、PNG、WebP，最多 5 MB。</span></div>`}
function statusField(r){return `<div class="panel"><h2>發布狀態</h2>${select('status','目前狀態',['draft','published'],r.status||'draft')}<p class="helper" style="margin-top:14px">選「published」才會出現在網站前台。</p></div>`}
function placeEditor(r){const tags=['食物','減廢','水','自然與生物多樣性','社區','文化','青年','重用','交通'];return head()+`<form id="record-form" class="editor"><div class="panel"><h2>地點內容</h2><div class="form-grid">${field('name','地點名稱',r.name||'','required')}${field('en','英文名稱（選填）',r.en||'')}${select('cat','生活入口',['食','買','修','去','學','參與'],r.cat||'去')}${select('area','地區',['澳門半島','氹仔','路環'],r.area||'澳門半島')}${field('address','地址',r.address||'','required wide')}<div class="field wide map-geocode-row"><button type="button" class="btn btn-outline" data-action="geocode">根據地址定位</button><span class="helper">使用 MapTiler 搜尋地址後，請在地圖上確認標點位置。</span></div>${field('hours','營業／開放時間',r.hours||'')}${field('phone','聯絡電話',r.phone||'')}${textarea('desc','簡短介紹',r.desc||'',3)}${textarea('story','詳細介紹／地方故事',r.story||'',9)}<div class="field wide"><strong>生態標籤</strong><div class="tag-grid">${tags.map(t=>`<label><input type="checkbox" name="tags" value="${t}" ${r.tags?.includes(t)?'checked':''}><span>${t}</span></label>`).join('')}</div></div><div class="field wide"><strong>地圖座標</strong><div id="map-picker" class="map-picker"></div><p class="map-hint">點選地圖或拖動標點，也可直接輸入座標。請確認位置在澳門。</p><div class="form-grid">${field('lat','緯度',r.lat??'','type="number" step="any" required')}${field('lng','經度',r.lng??'','type="number" step="any" required')}</div></div></div></div><div class="side-panel">${imageField(r)}${statusField(r)}</div><div class="form-footer"><button type="button" class="btn btn-outline" data-action="cancel">取消</button><button type="submit" class="btn btn-primary">儲存地點</button></div></form>`}
function articleEditor(r){return head()+`<form id="record-form" class="editor"><div class="panel"><h2>文章內容</h2><div class="form-grid">${field('title','文章標題',r.title||'','required wide')}${field('subtitle','摘要／引言',r.subtitle||'','wide')}${select('category','分類',['人物故事','地方故事','食物','減廢','社區','文化','青年'],r.category||'人物故事')}<label class="field">關聯地點<select name="place_id"><option value="">不關聯地點</option>${state.records.places.map(p=>`<option value="${esc(p.id)}" ${r.place_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${textarea('body','文章正文',r.body||'',18)}</div><p class="helper">以段落書寫；空行會在前台分段。可先儲存草稿，確認後再發布。</p></div><div class="side-panel">${imageField(r)}${statusField(r)}</div><div class="form-footer"><button type="button" class="btn btn-outline" data-action="cancel">取消</button><button type="submit" class="btn btn-primary">儲存文章</button></div></form>`}
function routeEditor(r){return head()+`<form id="record-form" class="editor"><div class="panel"><h2>路線內容</h2><div class="form-grid">${field('n','路線名稱',r.n||'','required wide')}${field('cat','主題分類',r.cat||'','wide')}${textarea('text','路線介紹',r.text||'',5)}${field('time','預計時間',r.time||'')}<div class="field wide"><strong>沿途地點（可調整次序）</strong><div class="route-stop-list" id="route-stops">${routeStops()}</div><select id="route-place-add" class="route-add"><option value="">＋ 加入一個地點</option>${state.records.places.filter(p=>!state.routeIds.includes(p.id)).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></div></div></div><div class="side-panel">${imageField(r)}${statusField(r)}</div><div class="form-footer"><button type="button" class="btn btn-outline" data-action="cancel">取消</button><button type="submit" class="btn btn-primary">儲存路線</button></div></form>`}
function routeStops(){return state.routeIds.map((id,i)=>{const p=state.records.places.find(x=>x.id===id);return `<div class="route-stop"><strong>${i+1}.</strong><span>${esc(p?.name||'已移除的地點')}</span><button type="button" data-route-up="${i}" aria-label="上移">↑</button><button type="button" data-route-down="${i}" aria-label="下移">↓</button><button type="button" data-route-remove="${i}" aria-label="移除">×</button></div>`}).join('')||'<span class="helper">尚未選擇地點。</span>'}
function submissions(){const all=state.records.submissions,rows=all.filter(s=>state.filter==='all'||s.status===state.filter);return head()+`<div class="toolbar"><select id="admin-filter"><option value="all">全部投稿</option>${['pending','approved','rejected'].map(s=>`<option value="${s}" ${state.filter===s?'selected':''}>${{pending:'待審核',approved:'已接受',rejected:'已拒絕'}[s]}</option>`).join('')}</select></div>${rows.length?rows.map(s=>`<article class="submission-card"><div class="submission-card-head"><div><small class="submission-meta">${esc(s.type)} · ${esc(s.area)} · ${esc(s.created_at?.slice(0,10))}</small><h3>${esc(s.name)}</h3></div><span class="badge ${esc(s.status)}">${{pending:'待審核',approved:'已接受',rejected:'已拒絕'}[s.status]}</span></div><p><strong>地點：</strong>${esc(s.address||'未提供')}</p><p>${esc(s.description)}</p><div class="tag-grid">${(s.tags||[]).map(t=>`<span>${esc(t)}</span>`).join('')}</div>${s.image?`<img src="${esc(s.image)}" alt="投稿圖片">`:''}<div class="submission-actions">${s.status==='pending'?`<button class="btn btn-primary" data-promote="${esc(s.id)}">轉為地點草稿</button><button class="btn btn-danger" data-reject="${esc(s.id)}">不採納</button>`:''}</div></article>`).join(''):`<div class="table-wrap"><div class="empty">目前沒有這個狀態的投稿。</div></div>`}`}
function render(){if(!state.authed){app.innerHTML=login();return}app.innerHTML=shell(state.edit?(state.tab==='places'?placeEditor(state.edit):state.tab==='articles'?articleEditor(state.edit):routeEditor(state.edit)):state.tab==='submissions'?submissions():list());if(state.edit&&state.tab==='places')setTimeout(initPicker,0)}
function initPicker(){const el=document.getElementById('map-picker');if(!el||!window.L)return;const lat=Number(document.querySelector('[name=lat]').value)||22.1905,lng=Number(document.querySelector('[name=lng]').value)||113.5439;pickerMap=L.map(el).setView([lat,lng],14);const tileUrl=state.maptilerKey?`https://api.maptiler.com/maps/basic-v2/{z}/{x}/{y}.png?key=${encodeURIComponent(state.maptilerKey)}`:'https://tile.openstreetmap.org/{z}/{x}/{y}.png';const attribution=state.maptilerKey?'&copy; MapTiler &copy; OpenStreetMap contributors':'&copy; OpenStreetMap contributors';L.tileLayer(tileUrl,{attribution,maxZoom:19}).addTo(pickerMap);pickerMarker=L.marker([lat,lng],{draggable:true}).addTo(pickerMap);const sync=point=>{document.querySelector('[name=lat]').value=point.lat.toFixed(6);document.querySelector('[name=lng]').value=point.lng.toFixed(6);pickerMarker.setLatLng(point)};pickerMap.on('click',e=>sync(e.latlng));pickerMarker.on('dragend',()=>sync(pickerMarker.getLatLng()))}
async function geocodeAddress(){if(!state.maptilerKey)throw new Error('MapTiler 尚未設定');const input=document.querySelector('[name=address]'),query=input?.value.trim();if(!query)throw new Error('請先輸入地址');const endpoint=`https://api.maptiler.com/geocoding/${encodeURIComponent(query+' 澳門')}.json?key=${encodeURIComponent(state.maptilerKey)}&limit=5&country=mo&proximity=113.5439,22.1987`;const response=await fetch(endpoint);if(!response.ok)throw new Error('地址搜尋暫時無法使用');const data=await response.json(),feature=data.features?.[0],center=feature?.center;if(!center)throw new Error('找不到這個地址，請補充街道或地區');const [lng,lat]=center;if(lat<22||lat>22.25||lng<113.45||lng>113.65)throw new Error('搜尋結果不在澳門範圍內');document.querySelector('[name=lat]').value=Number(lat).toFixed(6);document.querySelector('[name=lng]').value=Number(lng).toFixed(6);pickerMarker?.setLatLng([lat,lng]);pickerMap?.setView([lat,lng],17);toast('已根據地址定位，請確認標點位置')}
function closePicker(){if(pickerMap){pickerMap.remove();pickerMap=null;pickerMarker=null}}
function openEditor(record={}){closePicker();state.edit=record;state.routeIds=[...(record.ids||[])];render()}
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]'),action=e.target.closest('[data-action]'),edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]'),promote=e.target.closest('[data-promote]'),reject=e.target.closest('[data-reject]'),up=e.target.closest('[data-route-up]'),down=e.target.closest('[data-route-down]'),remove=e.target.closest('[data-route-remove]');try{
 if(tab){closePicker();state.tab=tab.dataset.tab;state.edit=null;state.fromSubmission=null;state.query='';state.filter='all';render()}
 else if(action){if(action.dataset.action==='new'){state.fromSubmission=null;openEditor({})}if(action.dataset.action==='cancel'){closePicker();state.edit=null;state.fromSubmission=null;render()}if(action.dataset.action==='logout'){await api('/api/admin/logout',{method:'POST'});state.authed=false;render()}if(action.dataset.action==='geocode'){await geocodeAddress()}}
 else if(edit){openEditor(state.records[state.tab].find(x=>x.id===edit.dataset.edit))}
 else if(del){const record=state.records[state.tab].find(x=>x.id===del.dataset.delete);if(!confirm(`確定刪除「${record.name||record.title||record.n}」？此操作無法復原。`))return;await api(`/api/admin/${state.tab}/${record.id}`,{method:'DELETE'});await refresh();toast('已刪除')}
 else if(promote){const s=state.records.submissions.find(x=>x.id===promote.dataset.promote);state.fromSubmission=s.id;state.tab='places';openEditor({name:s.name,area:s.area||'澳門半島',address:s.address,tags:s.tags,desc:s.description,img:s.image,cat:s.type==='地點／店舖'?'去':'參與',status:'draft'})}
 else if(reject){if(!confirm('確定不採納這份投稿？'))return;await api(`/api/admin/submissions/${reject.dataset.reject}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'rejected'})});await refresh();toast('投稿已標記為不採納')}
 else if(up||down||remove){const i=Number((up||down||remove).dataset.routeUp??(up||down||remove).dataset.routeDown??(up||down||remove).dataset.routeRemove);if(remove)state.routeIds.splice(i,1);else{const j=up?i-1:i+1;if(j>=0&&j<state.routeIds.length)[state.routeIds[i],state.routeIds[j]]=[state.routeIds[j],state.routeIds[i]]}document.getElementById('route-stops').innerHTML=routeStops();document.getElementById('route-place-add').innerHTML='<option value="">＋ 加入一個地點</option>'+state.records.places.filter(p=>!state.routeIds.includes(p.id)).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}
 }catch(error){toast(error.message)}});
document.addEventListener('change',async e=>{if(e.target.id==='admin-filter'){state.filter=e.target.value;render()}if(e.target.id==='route-place-add'&&e.target.value){state.routeIds.push(e.target.value);document.getElementById('route-stops').innerHTML=routeStops();e.target.querySelector(`option[value="${e.target.value}"]`)?.remove();e.target.value=''}if(e.target.id==='image-file'&&e.target.files?.[0]){const file=e.target.files[0];if(file.size>5_000_000){toast('圖片不能超過 5 MB');return}try{const result=await api('/api/upload',{method:'POST',headers:{'Content-Type':file.type},body:file});document.querySelector('[name=img]').value=result.url;const preview=document.getElementById('image-preview');preview.src=result.url;preview.hidden=false;toast('圖片已上傳')}catch(error){toast(error.message)}}if(['lat','lng'].includes(e.target.name)&&pickerMarker){const lat=Number(document.querySelector('[name=lat]').value),lng=Number(document.querySelector('[name=lng]').value);if(Number.isFinite(lat)&&Number.isFinite(lng)){pickerMarker.setLatLng([lat,lng]);pickerMap.panTo([lat,lng])}}});
document.addEventListener('input',e=>{if(e.target.id==='admin-search'){state.query=e.target.value;const caret=e.target.selectionStart;render();const el=document.getElementById('admin-search');el.focus();el.setSelectionRange(caret,caret)}});
document.addEventListener('submit',async e=>{if(e.target.id==='auth-form'){e.preventDefault();const fd=new FormData(e.target),password=fd.get('password');if(state.needsSetup&&password!==fd.get('confirm')){document.getElementById('auth-error').innerHTML='<div class="error">兩次密碼不一致。</div>';return}try{await api(state.needsSetup?'/api/admin/setup':'/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password,setupToken:fd.get('setupToken')||''})});state.authed=true;state.needsSetup=false;await refresh()}catch(error){document.getElementById('auth-error').innerHTML=`<div class="error">${esc(error.message)}</div>`}return}
 if(e.target.id==='record-form'){e.preventDefault();const fd=new FormData(e.target),kind=state.tab,record={};for(const [key,value]of fd.entries())if(key!=='tags')record[key]=value;if(kind==='places'){record.tags=fd.getAll('tags');record.lat=Number(record.lat);record.lng=Number(record.lng)}if(kind==='routes')record.ids=state.routeIds;const creating=!state.edit.id;try{const saved=await api(`/api/admin/${kind}${creating?'':`/${state.edit.id}`}`,{method:creating?'POST':'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(record)});if(state.fromSubmission){await api(`/api/admin/submissions/${state.fromSubmission}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'approved'})});state.fromSubmission=null}closePicker();state.edit=null;await refresh();toast(`${labels[kind]}已儲存${saved.status==='draft'?'為草稿':'並發布'}`)}catch(error){toast(error.message)}}});
init();
